import * as THREE from 'three';
import poseRaw from './data/tricuspidApparatusPose.json';

// ============================================================================
// Rigid T_TV pose of the tricuspid apparatus (Phase 2 of the RV plan)
// ----------------------------------------------------------------------------
// Data origin: src/model/cardiacGeometry/data/tricuspidApparatusPose.json, generated by
// scripts/optimizeTricuspidPose.mjs (constrained optimization over the untouched GLB).
// Report: VD_FASE2_20261107.md. Diagnosis: DIAGNOSTICO_VD_GEOMETRIA_20261107.md,
// Sections 2.4 and 4.1.
//
// T_TV(x) = R·(x − pivot) + pivot + t, no scale, in the GLB parent space
// (`CardioCraft_Integrated_Valvar_Candidate`). It is applied to the MATRIX of each apparatus node
// (annulus, 3 leaflets, 3 papillary muscles, 18 chordae), not to the vertices: the local geometry, the chordae
// mapping (chorda_topological_mapping.json), restLen, axialT, tipOffset and the opening/closing
// kinematics of valvarKinematicsComponent stay identical in local space and are carried
// rigidly by the pose (lengths and gaps preserved by construction).
// Setup only (allocates); never call per frame.
// ============================================================================

/** Reversion flag: false restores the original GLB pose (apparatus inside the LV). */
export const TRICUSPID_APPARATUS_POSE_ENABLED = true;

export interface TricuspidApparatusPose {
  /** rotation pivot: center (vertex mean) of the original tricuspid annulus */
  pivot: [number, number, number];
  /** rotation R as quaternion [x, y, z, w] */
  quaternion: [number, number, number, number];
  /** translation t applied after the rotation */
  translation: [number, number, number];
}

const raw = poseRaw as unknown as { pose: TricuspidApparatusPose };
export const TRICUSPID_APPARATUS_POSE: TricuspidApparatusPose = raw.pose;

const PAPILLARIES = ['anterior', 'posterior', 'septal'] as const;

/** The 25 nodes of the GLB tricuspid apparatus that receive T_TV. */
export const TRICUSPID_APPARATUS_NODE_NAMES: readonly string[] = (() => {
  const names = [
    'tricuspid_annulus',
    'tricuspid_anterior_leaflet',
    'tricuspid_posterior_leaflet',
    'tricuspid_septal_leaflet',
  ];
  for (const p of PAPILLARIES) names.push(`tricuspid_${p}_papillary_muscle`);
  for (const p of PAPILLARIES) for (let i = 1; i <= 6; i++) names.push(`tricuspid_${p}_chorda_${i}`);
  return names;
})();

/** 4×4 matrix of T_TV: T(pivot + t) · R · T(−pivot). */
export function tricuspidPoseMatrix(
  pose: TricuspidApparatusPose = TRICUSPID_APPARATUS_POSE,
  out: THREE.Matrix4 = new THREE.Matrix4(),
): THREE.Matrix4 {
  const [px, py, pz] = pose.pivot;
  const q = new THREE.Quaternion(pose.quaternion[0], pose.quaternion[1], pose.quaternion[2], pose.quaternion[3]).normalize();
  const rot = new THREE.Matrix4().makeRotationFromQuaternion(q);
  const toOrigin = new THREE.Matrix4().makeTranslation(-px, -py, -pz);
  const back = new THREE.Matrix4().makeTranslation(px + pose.translation[0], py + pose.translation[1], pz + pose.translation[2]);
  return out.copy(back).multiply(rot).multiply(toOrigin);
}

/**
  * Applies (enabled = true) or undoes (enabled = false) T_TV on the apparatus nodes under `root`.
  * Idempotent: the original TRS of each node is kept in userData.tricuspidPoseRest on the first call,
  * and the pose is always recomposed from it. Returns the number of nodes found.
 */
export function applyTricuspidApparatusPose(
  root: THREE.Object3D,
  enabled: boolean = TRICUSPID_APPARATUS_POSE_ENABLED,
  pose: TricuspidApparatusPose = TRICUSPID_APPARATUS_POSE,
): number {
  const M = tricuspidPoseMatrix(pose);
  const rest = new THREE.Matrix4();
  const posed = new THREE.Matrix4();
  let n = 0;
  for (let i = 0; i < TRICUSPID_APPARATUS_NODE_NAMES.length; i++) {
    const obj = root.getObjectByName(TRICUSPID_APPARATUS_NODE_NAMES[i]);
    if (!obj) continue;
    n++;
    const ud = obj.userData as { tricuspidPoseRest?: number[] };
    if (!ud.tricuspidPoseRest) {
      ud.tricuspidPoseRest = new THREE.Matrix4().compose(obj.position, obj.quaternion, obj.scale).toArray();
    }
    rest.fromArray(ud.tricuspidPoseRest);
    if (enabled) posed.multiplyMatrices(M, rest);
    else posed.copy(rest);
    posed.decompose(obj.position, obj.quaternion, obj.scale);
    obj.updateMatrix();
  }
  root.updateMatrixWorld(true);
  return n;
}

/**
  * Pose of the procedural annulus `tricuspidValveRef` of the HeartMesh17 wireframe (group at `basePosition`,
  * inner mesh with its own rotation): position = pivot + t + R·(base − pivot); quaternion = R.
 */
export function tricuspidFallbackRingPose(
  basePosition: readonly [number, number, number],
  enabled: boolean = TRICUSPID_APPARATUS_POSE_ENABLED,
  pose: TricuspidApparatusPose = TRICUSPID_APPARATUS_POSE,
): { position: [number, number, number]; quaternion: [number, number, number, number] } {
  if (!enabled) return { position: [basePosition[0], basePosition[1], basePosition[2]], quaternion: [0, 0, 0, 1] };
  const M = tricuspidPoseMatrix(pose);
  const p = new THREE.Vector3(basePosition[0], basePosition[1], basePosition[2]).applyMatrix4(M);
  const q = new THREE.Quaternion(pose.quaternion[0], pose.quaternion[1], pose.quaternion[2], pose.quaternion[3]).normalize();
  return { position: [p.x, p.y, p.z], quaternion: [q.x, q.y, q.z, q.w] };
}
